<div class="admin-title"><div><p class="eyebrow">CMS</p><h1>Manage content</h1></div></div><div class="tabs"><?php foreach(['service','solution','industry','project','testimonial','faq'] as $t):?><a class="<?=$type===$t?'active':''?>" href="/admin/content?type=<?=$t?>"><?=e(ucfirst($t))?>s</a><?php endforeach;?></div><details class="panel editor"><summary>+ Add <?=e($type)?></summary><form method="post" action="/admin/content/save"><?=csrf_field()?><input type="hidden" name="type" value="<?=e($type)?>"><?php require __DIR__.'/fields.php';?><button class="button">Create content</button></form></details><?php foreach($items as $item):?><details class="panel editor"><summary><span><b><?=e($item['title'])?></b><small>/<?=e($item['slug'])?></small></span><span class="badge"><?=e($item['status'])?></span></summary><form method="post" action="/admin/content/save"><?=csrf_field()?><input type="hidden" name="id" value="<?=$item['id']?>"><input type="hidden" name="type" value="<?=e($type)?>"><?php require __DIR__.'/fields.php';?><div class="editor-actions"><button class="button">Save changes</button></form><form method="post" action="/admin/content/delete" onsubmit="return confirm('Delete this item permanently?')"><?=csrf_field()?><input type="hidden" name="id" value="<?=$item['id']?>"><input type="hidden" name="type" value="<?=e($type)?>"><button class="danger">Delete</button></form></div></details><?php endforeach;?>
